insert into public.learning_units (id, topic_id, subtopic_id, title, unit_type, sequence_number, description, body, estimated_minutes, difficulty, status, created_by) values
  ('04427401-8118-52f9-bb5b-05e1493ce32f', '4b64262f-0eca-5ba5-bca0-e7aac67781f3', 'a36a2f5e-47e6-5f1b-a612-83bdb4dc57d6', 'What is a limit?', 'explanation', 1, 'A limit describes the value a function approaches as the input gets close to some point. We write lim x→a f(x) = L. Limi', 'A limit describes the value a function approaches as the input gets close to some point. We write lim x→a f(x) = L. Limits do not depend on the value of f at a — only on the behaviour near a. This distinction is what makes calculus possible.', 12, 1, 'approved', null),
  ('183b1a25-a306-599c-819e-193568a61baf', '4b64262f-0eca-5ba5-bca0-e7aac67781f3', 'a36a2f5e-47e6-5f1b-a612-83bdb4dc57d6', 'Estimating limits from tables', 'worked_example', 2, 'Evaluate f(x) for x approaching a from both sides. If both sides approach the same number, the limit exists. Example: fo', 'Evaluate f(x) for x approaching a from both sides. If both sides approach the same number, the limit exists. Example: for f(x)=(x²−1)/(x−1) near x=1, values approach 2, so the limit is 2 even though f(1) is undefined.', 10, 2, 'approved', null),
  ('7de8ab68-c3b8-579d-98b0-e545c0b92037', '4b64262f-0eca-5ba5-bca0-e7aac67781f3', 'a36a2f5e-47e6-5f1b-a612-83bdb4dc57d6', 'Limit laws', 'explanation', 3, 'The limit of a sum, difference, product and quotient equals the same combination of individual limits, provided the deno', 'The limit of a sum, difference, product and quotient equals the same combination of individual limits, provided the denominator''s limit is non-zero. These laws let us break complicated limits into simple pieces.', 14, 2, 'approved', null),
  ('ad97317f-23a5-50bf-8701-24798544cab7', '4b64262f-0eca-5ba5-bca0-e7aac67781f3', 'aba27331-965f-591f-8a00-746cdfca3207', 'Definition of continuity', 'explanation', 1, 'A function is continuous at a if f(a) is defined, lim x→a f(x) exists, and the limit equals f(a). Polynomials, rationals', 'A function is continuous at a if f(a) is defined, lim x→a f(x) exists, and the limit equals f(a). Polynomials, rationals on their domains, and trig functions are continuous where defined.', 10, 2, 'approved', null),
  ('24f89f97-9ae1-5e14-8349-1712e2458430', '6da11359-3901-5ab6-80fe-4a36571bf41d', '2a664186-035b-5a3b-8a99-cd5c47185511', 'Definition of the derivative', 'explanation', 1, 'f''(x) = lim h→0 [f(x+h) − f(x)]/h. This is the instantaneous rate of change and the slope of the tangent line. The whole', 'f''(x) = lim h→0 [f(x+h) − f(x)]/h. This is the instantaneous rate of change and the slope of the tangent line. The whole of differential calculus builds on this single limit.', 14, 3, 'approved', null),
  ('63b288a7-c0ab-5475-89f8-1618d9283f9f', '6da11359-3901-5ab6-80fe-4a36571bf41d', '2a664186-035b-5a3b-8a99-cd5c47185511', 'Power rule worked example', 'worked_example', 2, 'd/dx xⁿ = n xⁿ⁻¹. So d/dx x³ = 3x² and d/dx x⁵ = 5x⁴. Constants multiply through, and the derivative of a constant is ze', 'd/dx xⁿ = n xⁿ⁻¹. So d/dx x³ = 3x² and d/dx x⁵ = 5x⁴. Constants multiply through, and the derivative of a constant is zero.', 9, 1, 'approved', null),
  ('61a2411b-d1cb-526c-9cf0-c6cce1df0a13', '6da11359-3901-5ab6-80fe-4a36571bf41d', '2a664186-035b-5a3b-8a99-cd5c47185511', 'Product and quotient rules', 'explanation', 3, 'Product rule: (fg)'' = f''g + fg''. Quotient rule: (f/g)'' = (f''g − fg'')/g². Identify f and g before differentiating to avoi', 'Product rule: (fg)'' = f''g + fg''. Quotient rule: (f/g)'' = (f''g − fg'')/g². Identify f and g before differentiating to avoid sign errors.', 14, 3, 'approved', null),
  ('f08cbb1f-b8c4-5cdb-b97e-673db18946f0', 'fdb024fc-0c18-555d-b6b3-96782f5ab803', 'c7e56f84-028c-52ba-852b-902a4b0bd5e7', 'When substitution gives 0/0', 'explanation', 1, 'If lim f/g yields 0/0 or ∞/∞, l''Hôpital''s rule lets us differentiate numerator and denominator and take the limit again.', 'If lim f/g yields 0/0 or ∞/∞, l''Hôpital''s rule lets us differentiate numerator and denominator and take the limit again. Verify the indeterminate form before applying it.', 10, 3, 'approved', null),
  ('01896585-8d30-53d9-8c96-276ed8f50fbe', '5da94c7c-05ee-5962-8205-23a3cdb1f7d7', '8f816d37-5550-5f4a-83ea-2ba5d3e329ab', 'Classical probability', 'explanation', 1, 'P(A) = favourable outcomes / total outcomes. The complement rule: P(not A)=1−P(A). For disjoint events, P(A or B)=P(A)+P', 'P(A) = favourable outcomes / total outcomes. The complement rule: P(not A)=1−P(A). For disjoint events, P(A or B)=P(A)+P(B); for independent events, P(A and B)=P(A)P(B).', 12, 2, 'approved', null),
  ('c9d49774-0b2e-5357-a5ef-22bdf78756c2', 'efc19e27-aa57-5397-8132-ab6cf05ca9ff', 'b82c0fea-ea7f-53ac-a5c6-0a61d07c8539', 'Conduction, convection, radiation', 'explanation', 1, 'Heat moves by direct contact (conduction), fluid flow (convection) and electromagnetic waves (radiation). Q = mcΔT relat', 'Heat moves by direct contact (conduction), fluid flow (convection) and electromagnetic waves (radiation). Q = mcΔT relates heat transfer to temperature change.', 12, 2, 'approved', null),
  ('4914af35-7792-5181-bffa-11deb0104def', '0192b18a-da09-5a21-97ed-3ec4896528de', 'dbc99aac-be2b-5292-bc8a-a5f8c6cb5fe0', 'First law — inertia', 'explanation', 1, 'A body remains at rest or in uniform straight-line motion unless acted on by a net external force. This overturned the o', 'A body remains at rest or in uniform straight-line motion unless acted on by a net external force. This overturned the older idea that motion requires a continued cause.', 9, 1, 'approved', null),
  ('98a267f8-d37d-530d-9dbb-b8fb29719d82', '0192b18a-da09-5a21-97ed-3ec4896528de', 'dbc99aac-be2b-5292-bc8a-a5f8c6cb5fe0', 'Second law — F = ma', 'explanation', 2, 'The net force on an object equals its mass times its acceleration: ΣF = ma. Force and acceleration are vectors and point', 'The net force on an object equals its mass times its acceleration: ΣF = ma. Force and acceleration are vectors and point the same way. Use a free-body diagram to identify all forces.', 14, 2, 'approved', null),
  ('3105cee9-8904-5c15-a2aa-6b0661fdb8b4', '0192b18a-da09-5a21-97ed-3ec4896528de', 'dbc99aac-be2b-5292-bc8a-a5f8c6cb5fe0', 'Third law — action & reaction', 'explanation', 3, 'For every action there is an equal and opposite reaction. The two forces act on different bodies, so they never cancel e', 'For every action there is an equal and opposite reaction. The two forces act on different bodies, so they never cancel each other on a single object.', 9, 2, 'approved', null),
  ('296fe948-f035-5bca-a967-e09e87f4b39d', '0192b18a-da09-5a21-97ed-3ec4896528de', 'dbc99aac-be2b-5292-bc8a-a5f8c6cb5fe0', 'Solving force problems', 'worked_example', 4, 'A 5 kg box on a frictionless floor is pulled by a 20 N horizontal force. Acceleration a = F/m = 20/5 = 4 m/s². Always re', 'A 5 kg box on a frictionless floor is pulled by a 20 N horizontal force. Acceleration a = F/m = 20/5 = 4 m/s². Always resolve forces along convenient axes and apply ΣF = ma separately.', 12, 3, 'approved', null),
  ('077cd3b1-ca66-50f1-859d-2aa6ae49c292', '8c7f9402-0e43-5206-87d3-754f0a464ab9', 'c76a9c31-22d7-51f3-8edf-b793480f7a45', 'Kinetic and potential energy', 'explanation', 1, 'Kinetic energy K = ½mv². Gravitational potential energy U = mgh. In the absence of non-conservative forces, K + U is con', 'Kinetic energy K = ½mv². Gravitational potential energy U = mgh. In the absence of non-conservative forces, K + U is conserved.', 12, 2, 'approved', null),
  ('1d3d6ab3-847d-51d0-95dd-0876e5e1dca4', '8c7f9402-0e43-5206-87d3-754f0a464ab9', 'c76a9c31-22d7-51f3-8edf-b793480f7a45', 'Worked energy problem', 'worked_example', 2, 'A 2 kg ball dropped from 5 m converts potential energy mgh=98 J into kinetic energy at ground level. Its speed from ½mv²', 'A 2 kg ball dropped from 5 m converts potential energy mgh=98 J into kinetic energy at ground level. Its speed from ½mv²=98 is about 9.9 m/s.', 10, 3, 'approved', null),
  ('e9d18a71-09b6-565d-b202-4e915e64d2a3', '601c983b-0c63-5cf9-ad11-68317e164ff0', '27c1e06a-40f8-5c9c-a4be-9d9cc11349cf', 'Subatomic particles', 'explanation', 1, 'Atoms contain protons (positive), neutrons (neutral) in the nucleus, and electrons (negative) in orbitals. Atomic number', 'Atoms contain protons (positive), neutrons (neutral) in the nucleus, and electrons (negative) in orbitals. Atomic number = number of protons; mass number = protons + neutrons.', 10, 1, 'approved', null),
  ('ea5612eb-6939-5327-9c14-84693c17bca6', '601c983b-0c63-5cf9-ad11-68317e164ff0', '27c1e06a-40f8-5c9c-a4be-9d9cc11349cf', 'Electron configuration', 'explanation', 2, 'Electrons fill orbitals in order 1s, 2s, 2p, 3s, 3p… with at most two electrons per orbital (opposite spins). Configurat', 'Electrons fill orbitals in order 1s, 2s, 2p, 3s, 3p… with at most two electrons per orbital (opposite spins). Configuration explains periodic trends and bonding.', 14, 3, 'approved', null),
  ('458fa36d-6b7f-5811-9739-483997ad5539', 'b69b6510-ec1d-52b4-b1ff-e147b650beb7', 'aab6f4c7-9b49-5408-b476-c50b484d3b8e', 'Moles and molar mass', 'explanation', 1, 'One mole contains 6.022×10²³ particles. Molar mass converts between grams and moles: n = m/M. Balanced equations give mo', 'One mole contains 6.022×10²³ particles. Molar mass converts between grams and moles: n = m/M. Balanced equations give mole ratios between reactants and products.', 12, 2, 'approved', null),
  ('80e62f92-37c0-5325-88c2-09a2beb70b2a', 'b69b6510-ec1d-52b4-b1ff-e147b650beb7', 'aab6f4c7-9b49-5408-b476-c50b484d3b8e', 'Worked stoichiometry', 'worked_example', 2, 'For 2H₂ + O₂ → 2H₂O, 2 moles of H₂ react with 1 mole of O₂. To make 4 moles of water you need 4 moles H₂ and 2 moles O₂.', 'For 2H₂ + O₂ → 2H₂O, 2 moles of H₂ react with 1 mole of O₂. To make 4 moles of water you need 4 moles H₂ and 2 moles O₂.', 12, 3, 'approved', null),
  ('e3d3c3b6-f1ed-504c-a7a7-0f5182b057d6', 'cd6342d7-b02e-5872-b999-c38543ee3adb', 'c6b36054-d3c3-5acf-9065-ef26009fc82d', 'Subatomic particles', 'explanation', 1, 'Atoms contain protons (positive), neutrons (neutral) in the nucleus, and electrons (negative) in orbitals. Atomic number', 'Atoms contain protons (positive), neutrons (neutral) in the nucleus, and electrons (negative) in orbitals. Atomic number = number of protons; mass number = protons + neutrons.', 10, 1, 'approved', null),
  ('e2d642a8-9bad-57b4-8418-b275ed1f2f63', 'cd6342d7-b02e-5872-b999-c38543ee3adb', 'c6b36054-d3c3-5acf-9065-ef26009fc82d', 'Electron configuration', 'explanation', 2, 'Electrons fill orbitals in order 1s, 2s, 2p, 3s, 3p… with at most two electrons per orbital (opposite spins). Configurat', 'Electrons fill orbitals in order 1s, 2s, 2p, 3s, 3p… with at most two electrons per orbital (opposite spins). Configuration explains periodic trends and bonding.', 14, 3, 'approved', null),
  ('2c28190b-51cf-59a2-8a60-92904c66bbac', '8faa8531-f402-587c-b04d-d67d6be082bd', 'e8b2cf62-8035-5b5c-a2e0-b5a895b9e8a0', 'Moles and molar mass', 'explanation', 1, 'One mole contains 6.022×10²³ particles. Molar mass converts between grams and moles: n = m/M. Balanced equations give mo', 'One mole contains 6.022×10²³ particles. Molar mass converts between grams and moles: n = m/M. Balanced equations give mole ratios between reactants and products.', 12, 2, 'approved', null),
  ('fd17c0ae-a2cb-5d96-8020-e57d8016b001', '8faa8531-f402-587c-b04d-d67d6be082bd', 'e8b2cf62-8035-5b5c-a2e0-b5a895b9e8a0', 'Worked stoichiometry', 'worked_example', 2, 'For 2H₂ + O₂ → 2H₂O, 2 moles of H₂ react with 1 mole of O₂. To make 4 moles of water you need 4 moles H₂ and 2 moles O₂.', 'For 2H₂ + O₂ → 2H₂O, 2 moles of H₂ react with 1 mole of O₂. To make 4 moles of water you need 4 moles H₂ and 2 moles O₂.', 12, 3, 'approved', null),
  ('0cf0f662-dafe-5c4f-af98-597948c60538', '0e225589-c5c8-58db-8772-232aeaec9797', 'c834fa1c-c9d9-5617-ad19-6efe7beb36ee', 'Cell theory', 'explanation', 1, 'All organisms are made of cells; the cell is the basic unit of life; all cells arise from pre-existing cells. Cells are ', 'All organisms are made of cells; the cell is the basic unit of life; all cells arise from pre-existing cells. Cells are either prokaryotic (no nucleus) or eukaryotic (membrane-bound nucleus).', 8, 1, 'approved', null),
  ('badce5b0-c603-502a-ace2-2e1a59c78ce4', '0e225589-c5c8-58db-8772-232aeaec9797', 'c834fa1c-c9d9-5617-ad19-6efe7beb36ee', 'Organelles', 'explanation', 2, 'The nucleus stores DNA; mitochondria produce ATP; ribosomes build proteins; the ER and Golgi process and transport molec', 'The nucleus stores DNA; mitochondria produce ATP; ribosomes build proteins; the ER and Golgi process and transport molecules; chloroplasts (in plants) perform photosynthesis.', 14, 2, 'approved', null),
  ('5018db41-dd1b-5f6c-84bb-a23d88815127', 'c1fbf7c6-b8be-55b6-b42c-15d81ba78c79', '143caf4d-5143-5500-8fcb-7428babcfb39', 'Dominance and segregation', 'explanation', 1, 'Alleles can be dominant or recessive. A monohybrid cross Aa × Aa produces a genotypic ratio 1:2:1 and phenotypic ratio 3', 'Alleles can be dominant or recessive. A monohybrid cross Aa × Aa produces a genotypic ratio 1:2:1 and phenotypic ratio 3:1. Punnett squares make the combinations explicit.', 12, 2, 'approved', null),
  ('85850bc7-6239-57a0-a400-a2dded9e8ad1', '541bf6ea-5179-51b1-a6c5-594dc573a5ff', 'cc2fa26e-28d5-5582-a719-9947c315961d', 'Roots, stems and leaves', 'explanation', 1, 'Roots anchor the plant and absorb water; stems support and transport through xylem (water) and phloem (sugars); leaves a', 'Roots anchor the plant and absorb water; stems support and transport through xylem (water) and phloem (sugars); leaves are the main site of photosynthesis through stomata and chloroplasts.', 12, 2, 'approved', null),
  ('ea261c9f-d131-5bd8-b585-837e6f5b3ec7', '44fae898-5524-5067-a4da-5c161b399771', '2e29d4ef-fe72-5d45-a202-9f1ba60ed215', 'Bacterial growth curve', 'explanation', 1, 'Populations show lag, log (exponential), stationary and death phases. Growth depends on temperature, pH, nutrients and o', 'Populations show lag, log (exponential), stationary and death phases. Growth depends on temperature, pH, nutrients and oxygen.', 12, 2, 'approved', null),
  ('b92a1bd6-56ce-578f-a96a-dfd8b8b4912a', '44fae898-5524-5067-a4da-5c161b399771', '2e29d4ef-fe72-5d45-a202-9f1ba60ed215', 'Control methods', 'explanation', 2, 'Sterilisation kills all microbes; disinfection reduces pathogens on surfaces; antisepsis treats living tissue. Autoclavi', 'Sterilisation kills all microbes; disinfection reduces pathogens on surfaces; antisepsis treats living tissue. Autoclaving uses moist heat under pressure.', 10, 2, 'approved', null),
  ('589d49b9-f43a-5975-9870-d0e8412f719a', '63cb0067-ad12-561a-ad27-8682a3d00efe', '7d762465-0d88-5cd5-a6d1-c450a3f2e8a9', 'Trophic levels', 'explanation', 1, 'Energy flows from producers to primary consumers, secondary consumers and decomposers. Only about 10% transfers between ', 'Energy flows from producers to primary consumers, secondary consumers and decomposers. Only about 10% transfers between levels, which limits food-chain length and shapes ecosystem structure.', 12, 2, 'approved', null),
  ('6aeb552b-0f0f-53e5-95a5-e0c12f560963', '058437a6-8569-5b5f-98fd-9e5a97a7eaa8', '9b2396dc-4ba0-58a9-aa41-b010bdbd0efa', 'What pH means for soil', 'explanation', 1, 'pH measures hydrogen-ion activity. Most crops prefer pH 6.0–7.0 where nutrients are most available. Acidic soils are oft', 'pH measures hydrogen-ion activity. Most crops prefer pH 6.0–7.0 where nutrients are most available. Acidic soils are often limed; alkaline soils may need elemental sulphur or organic matter.', 12, 2, 'approved', null),
  ('d1781e3f-8ce5-582a-87d6-d7f82fb8745d', '49183d0a-c20d-5655-8d7d-6d8a665eee2c', 'b5ef49c9-bc0e-5630-857d-6d53ddf9dcd5', 'Binary and decimal', 'explanation', 1, 'Binary uses base 2 with digits 0 and 1. Each position is a power of two. 1011₂ = 1×8 + 0×4 + 1×2 + 1×1 = 11₁₀. Hexadecim', 'Binary uses base 2 with digits 0 and 1. Each position is a power of two. 1011₂ = 1×8 + 0×4 + 1×2 + 1×1 = 11₁₀. Hexadecimal (base 16) compactly represents groups of four bits.', 12, 2, 'approved', null),
  ('71d66cf8-b485-5ee5-bb53-9345d5384dcd', '49183d0a-c20d-5655-8d7d-6d8a665eee2c', 'b5ef49c9-bc0e-5630-857d-6d53ddf9dcd5', 'Conversion practice', 'worked_example', 2, 'Convert decimal 13 to binary: 13 = 8+4+1 = 1101₂. Convert back by summing powers of two from left to right.', 'Convert decimal 13 to binary: 13 = 8+4+1 = 1101₂. Convert back by summing powers of two from left to right.', 10, 2, 'approved', null),
  ('87b3ad5f-aee6-567e-9aa6-c73c6637b4c1', 'a9f82d8f-6794-51ab-a5b5-21a5a4923d7d', '022d6c23-4969-513c-b3b0-3ad909820597', 'State-space search', 'explanation', 1, 'A search problem has an initial state, actions, a transition model, a goal test and path cost. BFS explores level by lev', 'A search problem has an initial state, actions, a transition model, a goal test and path cost. BFS explores level by level and finds shortest paths in unweighted graphs; DFS dives deep first and uses less memory.', 14, 3, 'approved', null),
  ('ccb349bd-2b64-597e-9827-5efc44390f9d', 'a9f82d8f-6794-51ab-a5b5-21a5a4923d7d', '022d6c23-4969-513c-b3b0-3ad909820597', 'A* search', 'explanation', 2, 'A* uses f(n)=g(n)+h(n), combining cost-so-far with a heuristic estimate to the goal. With an admissible (never overestim', 'A* uses f(n)=g(n)+h(n), combining cost-so-far with a heuristic estimate to the goal. With an admissible (never overestimating) heuristic, A* is optimal.', 12, 4, 'approved', null),
  ('572ec251-6bbf-55cb-b3e7-817c2ca27622', '30e71f67-2f30-5113-93f8-035f9e78552c', 'f6ce4c6a-8e35-52a0-a861-f799f87816af', 'What is machine learning?', 'explanation', 1, 'ML systems learn patterns from examples instead of being explicitly programmed. Supervised learning maps inputs to label', 'ML systems learn patterns from examples instead of being explicitly programmed. Supervised learning maps inputs to labelled outputs; unsupervised learning finds structure; reinforcement learning learns by reward.', 12, 2, 'approved', null),
  ('bcc0ff86-6a61-50da-918f-a5e50668859c', '30e71f67-2f30-5113-93f8-035f9e78552c', 'f6ce4c6a-8e35-52a0-a861-f799f87816af', 'Overfitting', 'explanation', 2, 'A model overfits when it memorises training data but fails on new examples. Use held-out test data, simpler models and r', 'A model overfits when it memorises training data but fails on new examples. Use held-out test data, simpler models and regularisation to generalise better.', 10, 3, 'approved', null),
  ('f224a205-11f5-5513-a86b-44ad49003044', 'c187a6ec-34c4-58e6-8b06-b89adcb4641b', '2a4432b8-161f-537d-ab87-920e798f8096', 'Demand and supply curves', 'explanation', 1, 'Demand slopes downward (lower price → more demanded); supply slopes upward. Their intersection is the equilibrium price ', 'Demand slopes downward (lower price → more demanded); supply slopes upward. Their intersection is the equilibrium price and quantity. Shifters such as income, input costs or policy move the curves.', 14, 2, 'approved', null) on conflict (id) do nothing;
