  ('878824cf-c519-5b76-ba3d-0a24b2bed656', 'fdb024fc-0c18-555d-b6b3-96782f5ab803', 'c7e56f84-028c-52ba-852b-902a4b0bd5e7', 'true_false', 2, 'L''Hôpital''s rule applies to 0/0 and ∞/∞ forms.', 'These are the standard indeterminate forms it handles.', null, null, '{"key":"true"}'::jsonb, 90, 'approved', null),
  ('6c7735a0-b062-51e5-b4bd-4f47ed7b4457', '5da94c7c-05ee-5962-8205-23a3cdb1f7d7', '8f816d37-5550-5f4a-83ea-2ba5d3e329ab', 'multiple_choice', 1, 'A fair die rolls. P(even) =', 'Three even faces out of six = 1/2.', null, null, '{"key":"C"}'::jsonb, 90, 'approved', null),
  ('de85e7b9-31cd-5f19-a81e-64babbeaf7f4', '5da94c7c-05ee-5962-8205-23a3cdb1f7d7', '8f816d37-5550-5f4a-83ea-2ba5d3e329ab', 'true_false', 2, 'Independent events affect each other''s probability.', 'Independence means one does not change the other''s probability.', null, null, '{"key":"false"}'::jsonb, 90, 'approved', null),
  ('3e479539-363c-5367-a045-259cf432f984', 'efc19e27-aa57-5397-8132-ab6cf05ca9ff', 'b82c0fea-ea7f-53ac-a5c6-0a61d07c8539', 'multiple_choice', 1, 'Heat transfer through empty space occurs by:', 'Radiation does not require a medium.', null, null, '{"key":"C"}'::jsonb, 90, 'approved', null),
  ('0e23815a-078a-5adc-b7a5-9b522c912f5f', '0192b18a-da09-5a21-97ed-3ec4896528de', 'dbc99aac-be2b-5292-bc8a-a5f8c6cb5fe0', 'multiple_choice', 1, 'A 5 kg object experiences a net force of 20 N. Its acceleration is:', 'a = F/m = 20/5 = 4 m/s².', 'Use F = ma and rearrange.', null, '{"key":"B"}'::jsonb, 90, 'approved', null),
  ('66cfa911-e5cb-5c05-853e-809556f626f4', '0192b18a-da09-5a21-97ed-3ec4896528de', 'dbc99aac-be2b-5292-bc8a-a5f8c6cb5fe0', 'true_false', 1, 'Newton''s third law forces always act on the same object.', 'Action–reaction pairs act on different bodies.', null, null, '{"key":"false"}'::jsonb, 90, 'approved', null),
  ('93009cb4-d325-52a3-8eaf-346d2ea25ee9', '0192b18a-da09-5a21-97ed-3ec4896528de', 'dbc99aac-be2b-5292-bc8a-a5f8c6cb5fe0', 'multiple_choice', 2, 'Inertia is the tendency of an object to:', 'Inertia is resistance to changes in velocity, measured by mass.', null, null, '{"key":"B"}'::jsonb, 90, 'approved', null),
