  ('10a8c5d8-f48f-5ca0-bd2d-a9b579a9390e', '8c7f9402-0e43-5206-87d3-754f0a464ab9', 'c76a9c31-22d7-51f3-8edf-b793480f7a45', 'true_false', 1, 'Mechanical energy is conserved when only conservative forces act.', 'With no friction or drag, K + U stays constant.', null, null, '{"key":"true"}'::jsonb, 90, 'approved', null),
  ('2b2cd6c7-a24c-5e10-b80f-e6b206441918', '601c983b-0c63-5cf9-ad11-68317e164ff0', '27c1e06a-40f8-5c9c-a4be-9d9cc11349cf', 'multiple_choice', 1, 'Which particle determines the element?', 'Atomic number (proton count) defines the element.', null, null, '{"key":"C"}'::jsonb, 90, 'approved', null),
  ('50914eb7-731f-5c56-9182-35a02697d6ae', '601c983b-0c63-5cf9-ad11-68317e164ff0', '27c1e06a-40f8-5c9c-a4be-9d9cc11349cf', 'short_answer', 1, 'A covalent bond involves ______ of electrons.', 'Covalent bonds form when atoms share electron pairs.', null, null, '{"value":"sharing"}'::jsonb, 90, 'approved', null),
  ('c42729d3-c695-5219-a35d-4e05b1b0b486', 'b69b6510-ec1d-52b4-b1ff-e147b650beb7', 'aab6f4c7-9b49-5408-b476-c50b484d3b8e', 'numeric', 2, 'How many moles of H₂O form from 4 mol H₂ in 2H₂+O₂→2H₂O?', 'The ratio of H₂ to H₂O is 1:1, so 4 mol H₂ yields 4 mol H₂O.', 'Use the mole ratio from the balanced equation.', null, '{"number":4}'::jsonb, 90, 'approved', null),
