-- StudyLab 0003 — curriculum content seed.
-- Inserts topics, subtopics, skills, learning units, resources, questions,
-- practicals and course offerings for the LUANAR BSc NAS programme.
-- Re-runnable: uses deterministic UUIDs and ON CONFLICT DO NOTHING.
-- Apply AFTER 0001 and 0002.

-- Course offerings (one per course in the active Year 2 Semester 1 period).
select gen_random_uuid(), c.id, ap.id, null, 'active'
from public.courses c
join public.academic_periods ap on ap.programme_id = c.programme_id and ap.year_level = 2 and ap.semester = 1
where c.status = 'confirmed'
on conflict do nothing;

